#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *parent;
    unsigned char *rank;              /* rank <= floor(lg n), fits in a byte */
} DSU;

DSU dsu_make(int n) {
    DSU d = { malloc(n * sizeof(int)), calloc(n, 1) };
    for (int i = 0; i < n; i++)
        d.parent[i] = i;              /* MAKE-SET(i) */
    return d;
}

int dsu_find(DSU *d, int x) {
    int root = x;
    while (d->parent[root] != root)   /* pass 1: locate the root */
        root = d->parent[root];
    while (d->parent[x] != root) {    /* pass 2: path compression */
        int next = d->parent[x];
        d->parent[x] = root;
        x = next;
    }
    return root;
}

/* Returns 1 if two different sets were merged, 0 if a and b were already together. */
int dsu_union(DSU *d, int a, int b) {
    int ra = dsu_find(d, a), rb = dsu_find(d, b);
    if (ra == rb) return 0;
    if (d->rank[ra] < d->rank[rb]) { int t = ra; ra = rb; rb = t; }
    d->parent[rb] = ra;               /* link lower rank under higher */
    if (d->rank[ra] == d->rank[rb]) d->rank[ra]++;
    return 1;
}

int main(void) {
    DSU d = dsu_make(8);
    int ops[][2] = {{0,1}, {2,3}, {0,2}, {4,5}, {6,7}, {4,6}, {0,4}};
    for (int i = 0; i < 7; i++)
        dsu_union(&d, ops[i][0], ops[i][1]);
    int r = dsu_find(&d, 7);
    printf("find(7) = %d, rank = %d, parent[6] = %d\n", r, d.rank[r], d.parent[6]);
    free(d.parent);
    free(d.rank);
    return 0;
}
